#include <array>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

using i64 = std::int64_t;

struct Gaussian {
    i64 re;
    i64 im;
};

static Gaussian add(Gaussian left, Gaussian right) {
    return {left.re + right.re, left.im + right.im};
}

static Gaussian subtract(Gaussian left, Gaussian right) {
    return {left.re - right.re, left.im - right.im};
}

static Gaussian multiply(Gaussian left, Gaussian right) {
    return {left.re * right.re - left.im * right.im, left.re * right.im + left.im * right.re};
}

static Gaussian conjugate(Gaussian value) {
    return {value.re, -value.im};
}

static i64 modulus_squared(Gaussian value) {
    return value.re * value.re + value.im * value.im;
}

static std::pair<int, Gaussian> pauli_action(char op, int bit) {
    switch (op) {
        case 'i': return {bit, {1, 0}};
        case 'x': return {1 - bit, {1, 0}};
        case 'y': return {1 - bit, {0, bit == 0 ? 1 : -1}};
        case 'z': return {bit, {bit == 0 ? 1 : -1, 0}};
        default: throw std::runtime_error("invalid Pauli operator");
    }
}

static i64 pauli_numerator(const std::array<Gaussian, 4>& amplitudes, const std::string& label) {
    Gaussian total{0, 0};
    for (int basis = 0; basis < 4; ++basis) {
        const int first_bit = basis >> 1;
        const int second_bit = basis & 1;
        const auto [mapped_first, first_phase] = pauli_action(label[0], first_bit);
        const auto [mapped_second, second_phase] = pauli_action(label[1], second_bit);
        const int mapped = 2 * mapped_first + mapped_second;
        const Gaussian phase = multiply(first_phase, second_phase);
        const Gaussian term = multiply(conjugate(amplitudes[mapped]), multiply(phase, amplitudes[basis]));
        total = add(total, term);
    }
    if (total.im != 0) throw std::runtime_error("Hermitian expectation was not real");
    return total.re;
}

static std::vector<i64> parse_csv_integers(const std::string& line) {
    std::vector<i64> values;
    std::stringstream stream(line);
    std::string token;
    while (std::getline(stream, token, ',')) values.push_back(std::stoll(token));
    return values;
}

int main() {
    constexpr std::array<const char*, 15> labels{
        "ix", "iy", "iz", "xi", "xx", "xy", "xz", "yi", "yx", "yy", "yz", "zi", "zx", "zy", "zz"
    };
    std::cout
        << "row_index,amplitude_norm_squared,amplitude_support_size,amplitude_fourth_moment_numerator,"
        << "determinant_modulus_squared_numerator,concurrence_squared_numerator,"
        << "first_bloch_squared_norm_numerator,second_bloch_squared_norm_numerator,"
        << "correlation_tensor_squared_norm_numerator";
    for (const char* label : labels) std::cout << ",pauli_" << label << "_numerator";
    std::cout << '\n';

    std::string line;
    while (std::getline(std::cin, line)) {
        if (line.empty()) continue;
        const std::vector<i64> values = parse_csv_integers(line);
        if (values.size() != 9) throw std::runtime_error("expected row index and eight amplitude components");
        const i64 row_index = values[0];
        std::array<Gaussian, 4> amplitudes{};
        for (int index = 0; index < 4; ++index) {
            amplitudes[index] = {values[1 + 2 * index], values[2 + 2 * index]};
        }

        i64 norm_squared = 0;
        i64 support_size = 0;
        i64 fourth_moment = 0;
        for (Gaussian amplitude : amplitudes) {
            const i64 modulus = modulus_squared(amplitude);
            norm_squared += modulus;
            support_size += modulus != 0 ? 1 : 0;
            fourth_moment += modulus * modulus;
        }
        const Gaussian determinant = subtract(
            multiply(amplitudes[0], amplitudes[3]),
            multiply(amplitudes[1], amplitudes[2])
        );
        const i64 determinant_squared = modulus_squared(determinant);

        std::array<i64, 15> expectations{};
        for (std::size_t index = 0; index < labels.size(); ++index) {
            expectations[index] = pauli_numerator(amplitudes, labels[index]);
        }
        const i64 first_bloch = expectations[3] * expectations[3]
            + expectations[7] * expectations[7] + expectations[11] * expectations[11];
        const i64 second_bloch = expectations[0] * expectations[0]
            + expectations[1] * expectations[1] + expectations[2] * expectations[2];
        i64 correlation = 0;
        for (std::size_t index : {4U, 5U, 6U, 8U, 9U, 10U, 12U, 13U, 14U}) {
            correlation += expectations[index] * expectations[index];
        }

        std::cout << row_index << ',' << norm_squared << ',' << support_size << ',' << fourth_moment << ','
                  << determinant_squared << ',' << 4 * determinant_squared << ',' << first_bloch << ','
                  << second_bloch << ',' << correlation;
        for (i64 expectation : expectations) std::cout << ',' << expectation;
        std::cout << '\n';
    }
    return 0;
}

